 plus:'<path d="M12 5v14M5 12h14"/>',minus:'<path d="M5 12h14"/>',
 undo:'<path d="M9 14 4 9l5-5M4 9h9a7 7 0 0 1 0 14"/>',
 redo:'<path d="m15 14 5-5-5-5M20 9h-9a7 7 0 0 0 0 14"/>',
 save:'<path d="M4 3h14l3 3v15H3V3h1ZM7 3v7h10V3M7 21v-8h10v8"/>',
 sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M2 12h2M20 12h2M5 5l2 2M17 17l2 2M19 5l-2 2M7 17l-2 2"/>',
