 command:'<path d="M9 7V5a3 3 0 1 0-3 3h2v8H6a3 3 0 1 0 3 3v-2h6v2a3 3 0 1 0 3-3h-2V8h2a3 3 0 1 0-3-3v2H9Z"/>',
 chevron:'<path d="m6 9 6 6 6-6"/>',
 arrow:'<path d="M4 12h16m-7-7 7 7-7 7"/>',
 check:'<path d="m4 12 5 5L20 6"/>',
 close:'<path d="M5 5 19 19M19 5 5 19"/>',
 trash:'<path d="M4 7h16M9 7V4h6v3M6 7l1 14h10l1-14M10 11v6M14 11v6"/>',
 clipboard:'<rect x="6" y="5" width="15" height="17" rx="2"/><path d="M10 5V3h-7v15h3"/>',
 download:'<path d="M12 3v12m-5-5 5 5 5-5M4 18v3h16v-3"/>',
 code:'<path d="m8 7-5 5 5 5m8-10 5 5-5 5m-2-15-4 20"/>',
